/**
 * Get the ZIP code for a given area key and city name.
 * Tries exact match first, then common variations
 * (e.g. "X City" ↔ "X", "Sto." ↔ "Santo", hyphen variations).
 * Returns an empty string if not found.
 */
function getCityZipCode(areaKey: string, city: string): string {
  const areaZips = ZIP_BY_AREA[areaKey];
  if (!areaZips) return '';

  // Try exact match first
  if (areaZips[city]) return areaZips[city];

  // Build list of variations to try
  const variations: string[] = [];

  // "X City" → "X"
  if (city.endsWith(' City')) {
    variations.push(city.slice(0, -5));
  }
  // "X" → "X City"
  variations.push(city + ' City');

  // "Sto." ↔ "Santo"
  if (city.startsWith('Sto. ')) {
    variations.push('Santo' + city.slice(4));
  }
  if (city.startsWith('Santo ')) {
    variations.push('Sto.' + city.slice(5));
  }

  // Hyphen removal (e.g. "Jala-Jala" → "Jalajala")
  if (city.includes('-')) {
    variations.push(city.replace(/-/g, ''));
  }

  // Try each variation
  for (const variant of variations) {
    if (areaZips[variant]) return areaZips[variant];
  }

  // Fuzzy match: check if city is a substring of any key (catches "Famy" matching "Famy (Famy)")
  for (const key of Object.keys(areaZips)) {
    if (key.startsWith(city + ' ') || key.endsWith(' ' + city)) {
      return areaZips[key];
    }
  }

  return '';
}

