export const ZIP_BY_BARANGAY: Record<string, Record<string, Record<string, string>>> =
  Object.fromEntries(Object.entries(WORKBOOK_LOCATIONS).map(([area, cities]) => [
    area,
    Object.fromEntries(Object.entries(cities).map(([city, barangays]) => [
      city, Object.fromEntries(Object.entries(barangays).map(([barangay, row]) => [barangay, row.zip])),
    ])),
  ]));

/** All distinct ZIP options, in workbook order. Unknown workbook locations do not use city defaults. */
export function getZipCodes(areaKey: string, barangay: string, city: string): string[] {
  if (!barangay || !city) return [];
  const zip = WORKBOOK_LOCATIONS[areaKey]
    ? ZIP_BY_BARANGAY[areaKey]?.[city]?.[barangay]
    : getCityZipCode(areaKey, city);
  return zip ? [...new Set(zip.split(',').map(value => value.trim()))] : [];
}

/** Only auto-fill an unambiguous postal code. Multiple codes require a selection. */
export function getZipCode(areaKey: string, barangay: string, city: string): string {
  const codes = getZipCodes(areaKey, barangay, city);
  return codes.length === 1 ? codes[0] : '';
}
